'use client'

import Link from 'next/link'
import { useEffect, useState } from 'react'
import { createClient } from '@/lib/supabase/client'
import { getUserRole } from '@/lib/supabase/roles'
import { notificationTypeLabels, type NotificationPreferences, type VendorNotification, vendorNotificationService } from '@/lib/vendor/notifications'
import { CatalogFeedback } from '../components/CatalogFeedback'
import { NotificationItem } from '../components/NotificationItem'

export default function VendorNotificationsPage() { const [vendorId, setVendorId] = useState<string | null>(null); const [notifications, setNotifications] = useState<VendorNotification[]>([]); const [preferences, setPreferences] = useState<NotificationPreferences | null>(null); const [loading, setLoading] = useState(true); useEffect(() => { void createClient().auth.getUser().then(async ({ data: { user } }) => { if (user && (getUserRole(user) === 'vendor' || getUserRole(user) === 'admin')) { setVendorId(user.id); setNotifications(await vendorNotificationService.list(user.id)); setPreferences(await vendorNotificationService.getPreferences(user.id)) } setLoading(false) }) }, []); async function refresh() { if (vendorId) setNotifications(await vendorNotificationService.list(vendorId)) } async function togglePreference(field: keyof NotificationPreferences) { if (!vendorId || !preferences) return; const next = { ...preferences, [field]: !preferences[field] }; setPreferences(await vendorNotificationService.savePreferences(vendorId, next)) } if (loading) return <main className="vendor-page"><div className="operations-shell"><CatalogFeedback type="loading">Loading notifications...</CatalogFeedback></div></main>; const unread = notifications.filter((item) => !item.readAt).length; return <main className="vendor-page"><header className="vendor-header"><Link href="/vendor" className="logo logo-active">Furnish<span>AI</span></Link><nav><Link href="/vendor" className="btn-skip">Portal</Link><span className="vendor-header-label">Notifications</span></nav></header><div className="operations-shell"><div className="operations-heading"><div><p className="vendor-eyebrow">Vendor operations</p><h1>Notifications</h1><p>Stay close to approvals, uploads, documents, and listing health.</p></div>{unread ? <button type="button" className="btn-skip" onClick={async () => { if (vendorId) await vendorNotificationService.markAllRead(vendorId); await refresh() }}>Mark all read</button> : null}</div><div className="operations-two-column"><section className="operations-panel"><div className="operations-panel-heading"><h2>Inbox</h2><span>{unread} unread</span></div>{notifications.length ? <div className="notification-list">{notifications.map((notification) => <NotificationItem key={notification.id} notification={notification} onRead={async (id) => { if (vendorId) await vendorNotificationService.markRead(vendorId, id); await refresh() }} />)}</div> : <div className="operations-empty"><h2>Nothing new</h2><p>Important vendor updates will appear here.</p></div>}</section><section className="operations-panel"><div className="operations-panel-heading"><h2>Preferences</h2></div><p className="operations-copy">Choose which operational updates should reach your inbox.</p>{preferences ? <div className="preference-list">{Object.entries(preferences).map(([field, enabled]) => <label key={field}><input type="checkbox" checked={enabled} onChange={() => void togglePreference(field as keyof NotificationPreferences)} /><span>{field.replace(/([A-Z])/g, ' $1').replace(/^./, (value) => value.toUpperCase())}</span></label>)}</div> : null}<p className="operations-note">Notification categories: {Object.values(notificationTypeLabels).join(', ')}.</p></section></div></div></main> }